package com.receiptledger.v1;
import android.app.Activity;import android.content.*;import android.graphics.Bitmap;import android.net.Uri;import android.os.Bundle;import android.provider.MediaStore;import android.view.Gravity;import android.widget.*;import com.receiptledger.v1.document.*;import com.receiptledger.v1.image.*;import com.receiptledger.v1.item.*;import com.receiptledger.v1.layout.*;import com.receiptledger.v1.ocr.*;import com.receiptledger.v1.structure.*;import com.receiptledger.v1.ui.DocumentPreviewView;import java.io.*;import java.util.concurrent.*;
public final class MainActivity extends Activity {private static final int REQ_CAMERA=1001,REQ_PICK=1002;private final ExecutorService worker=Executors.newSingleThreadExecutor();private final ReceiptDocumentDetector detector=new ReceiptDocumentDetector();private final ReceiptLayoutAnalyzer layoutAnalyzer=new ReceiptLayoutAnalyzer();private final ReceiptStructureAnalyzer structureAnalyzer=new ReceiptStructureAnalyzer();private final ItemTupleSolver itemSolver=new ItemTupleSolver();private final MlKitOcrEngine ocrEngine=new MlKitOcrEngine();private DocumentPreviewView preview;private TextView status,ocrText;private Button correctButton,originalButton,ocrButton;private Uri pendingCaptureUri;private Bitmap sourceBitmap,correctedBitmap,displayBitmap;private Quad detectedQuad;private PerspectivePlan correctedPlan;private ProjectiveTransform displayToSource=ProjectiveTransform.identity();private long generation,displayRevision;
@Override protected void onCreate(Bundle b){super.onCreate(b);int p=dp(12);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(p,p,p,p);root.setGravity(Gravity.CENTER_HORIZONTAL);TextView title=new TextView(this);title.setText(R.string.document_title);title.setTextSize(23);title.setGravity(Gravity.CENTER);LinearLayout a=new LinearLayout(this);a.setOrientation(LinearLayout.HORIZONTAL);a.setGravity(Gravity.CENTER);Button camera=button(R.string.capture,v->launchCamera()),gallery=button(R.string.gallery,v->launchPicker());correctButton=button(R.string.correct,v->correctPerspective());originalButton=button(R.string.original,v->showOriginal());ocrButton=button(R.string.run_ocr,v->runOcr());correctButton.setEnabled(false);originalButton.setEnabled(false);ocrButton.setEnabled(false);a.addView(camera);a.addView(gallery);a.addView(correctButton);a.addView(originalButton);a.addView(ocrButton);preview=new DocumentPreviewView(this);status=new TextView(this);status.setText(R.string.item_body);status.setTextSize(14);status.setPadding(0,p,0,0);ocrText=new TextView(this);ocrText.setTextSize(13);ocrText.setMaxLines(12);ocrText.setTextIsSelectable(true);ocrText.setPadding(0,dp(8),0,0);root.addView(title,new LinearLayout.LayoutParams(-1,-2));root.addView(a,new LinearLayout.LayoutParams(-1,-2));root.addView(preview,new LinearLayout.LayoutParams(-1,0,1f));root.addView(status,new LinearLayout.LayoutParams(-1,-2));root.addView(ocrText,new LinearLayout.LayoutParams(-1,-2));setContentView(root);}private Button button(int s,android.view.View.OnClickListener l){Button b=new Button(this);b.setText(s);b.setOnClickListener(l);return b;}
private void launchCamera(){try{File d=new File(getCacheDir(),"captures");if(!d.exists()&&!d.mkdirs())throw new IOException("Cannot create capture directory");File f=File.createTempFile("receipt_",".jpg",d);pendingCaptureUri=new Uri.Builder().scheme("content").authority(getPackageName()+".capture").appendPath(f.getName()).build();Intent i=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);i.putExtra(MediaStore.EXTRA_OUTPUT,pendingCaptureUri);i.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newRawUri("ReceiptLedger capture",pendingCaptureUri));if(i.resolveActivity(getPackageManager())==null){Toast.makeText(this,R.string.no_camera,Toast.LENGTH_SHORT).show();return;}startActivityForResult(i,REQ_CAMERA);}catch(IOException e){Toast.makeText(this,getString(R.string.load_failed,e.getMessage()),Toast.LENGTH_LONG).show();}}
private void launchPicker(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/*");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,REQ_PICK);}@Override protected void onActivityResult(int rc,int r,Intent data){super.onActivityResult(rc,r,data);if(r!=RESULT_OK)return;Uri u=null;if(rc==REQ_CAMERA)u=pendingCaptureUri;else if(rc==REQ_PICK&&data!=null){u=data.getData();if(u!=null)try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}}if(u!=null)loadImage(u);}
private void loadImage(Uri u){long t=++generation;displayRevision++;status.setText(R.string.loading);ocrText.setText("");correctButton.setEnabled(false);originalButton.setEnabled(false);ocrButton.setEnabled(false);worker.execute(()->{try{ImageLoader.LoadedImage l=ImageLoader.load(this,u);BitmapLumaAdapter.Sampled s=BitmapLumaAdapter.sample(l.bitmap,480);DocumentDetection d=detector.detect(s.plane);Quad q=d.found?s.toSource(d.quad):null;runOnUiThread(()->{if(t!=generation){l.bitmap.recycle();return;}if(sourceBitmap!=null&&sourceBitmap!=l.bitmap)sourceBitmap.recycle();if(correctedBitmap!=null){correctedBitmap.recycle();correctedBitmap=null;}sourceBitmap=l.bitmap;correctedPlan=null;detectedQuad=q;displayBitmap=sourceBitmap;displayToSource=ProjectiveTransform.identity();displayRevision++;preview.setDocument(sourceBitmap,detectedQuad);correctButton.setEnabled(q!=null);originalButton.setEnabled(false);ocrButton.setEnabled(true);status.setText(d.found?getString(R.string.detected,d.confidence,l.bitmap.getWidth(),l.bitmap.getHeight(),l.exifOrientation):getString(R.string.not_detected,d.reason,l.bitmap.getWidth(),l.bitmap.getHeight()));});}catch(Exception e){runOnUiThread(()->{if(t==generation)status.setText(getString(R.string.load_failed,e.getMessage()));});}});}
private void correctPerspective(){final Bitmap b=sourceBitmap;final Quad q=detectedQuad;if(b==null||q==null)return;long t=generation;status.setText(R.string.correcting);correctButton.setEnabled(false);worker.execute(()->{try{PerspectiveWarp.Result r=PerspectiveWarp.warp(b,q);runOnUiThread(()->{if(t!=generation){r.bitmap.recycle();return;}if(correctedBitmap!=null)correctedBitmap.recycle();correctedBitmap=r.bitmap;correctedPlan=r.plan;displayBitmap=correctedBitmap;displayToSource=correctedPlan.outputToSource;displayRevision++;preview.setDocument(correctedBitmap,null);ocrText.setText("");originalButton.setEnabled(true);correctButton.setEnabled(true);ocrButton.setEnabled(true);status.setText(getString(R.string.corrected,r.plan.outputWidth,r.plan.outputHeight));});}catch(Exception e){runOnUiThread(()->{if(t==generation){correctButton.setEnabled(true);status.setText(getString(R.string.correction_failed,e.getMessage()));}});}});}private void showOriginal(){if(sourceBitmap==null)return;displayBitmap=sourceBitmap;displayToSource=ProjectiveTransform.identity();displayRevision++;preview.setDocument(sourceBitmap,detectedQuad);ocrText.setText("");status.setText(R.string.showing_original);ocrButton.setEnabled(true);}
private void runOcr(){final Bitmap input=displayBitmap;if(input==null)return;final ProjectiveTransform mapper=displayToSource;final long it=generation,vt=displayRevision;ocrButton.setEnabled(false);status.setText(R.string.ocr_running);preview.setOcrQuads(null);ocrEngine.recognize(input,mapper,new MlKitOcrEngine.Callback(){public void onSuccess(OcrDocument doc){if(it!=generation||vt!=displayRevision)return;ocrButton.setEnabled(true);preview.setOcrQuads(doc.inputElementQuads());ReceiptLayout layout=layoutAnalyzer.analyze(doc);ReceiptStructure structure=structureAnalyzer.analyze(layout);ItemTupleResult items=itemSolver.solve(structure);StringBuilder s=new StringBuilder("[상품 후보]\n");for(ItemTuple item:items.items)s.append('[').append(item.resolution).append("] ").append(item.name).append(" | q=").append(item.quantity).append(" | unit=").append(item.unitPrice).append(" | amount=").append(item.lineAmount).append(" {").append(item.reason).append("}\n");s.append("\n[구조 행]\n");for(StructuredRow row:structure.rows)s.append('[').append(row.role).append("] ").append(row.row.text).append('\n');ocrText.setText(s.toString());status.setText(getString(R.string.item_done,items.items.size(),items.exactCount,items.inferredCount,items.partialCount));}public void onFailure(Exception e){if(it!=generation||vt!=displayRevision)return;ocrButton.setEnabled(true);status.setText(getString(R.string.ocr_failed,e.getMessage()));}});}
@Override protected void onDestroy(){generation++;displayRevision++;worker.shutdownNow();ocrEngine.close();super.onDestroy();}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}}
